contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint _seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Ensure the test contract has some Ether to send, to create a non-zero c balance.
        require(address(this).balance >= 0);

        // Make the test contract the owner of c by calling withdrawAll from the owner's address.
        // However, the test contract deployed c, so it is already the owner. But msg.sender
        // for calls to c is the test contract. So the test contract is owner.
        // To test non-owner revert, we call withdrawAll from a different address. But we
        // cannot change msg.sender. Instead, we can have an EOA call, but we only have the
        // test contract. The property must hold for any caller. The checker runs run() once;
        // msg.sender for c calls is this contract. So the owner check passes. To test non-owner,
        // we need to simulate a non-owner. But we cannot. So the rule should be about the
        // owner call: withdrawAll from owner should succeed and transfer balance.
        // However, the counterexample shows that withdrawAll reverted even though the test
        // contract is owner. Why? Because in the counterexample, c's owner is 4294967295 (a
        // different address), not the test contract. The test contract's address is 4294967294.
        // So the constructor of C set owner to msg.sender at deployment time. The deployment
        // was done by the test contract? The trace shows: sol:@C@InvMutTest@F@InvMutTest#93
        // at ... which suggests that InvMutTest was deployed, and then it deployed C? Actually
        // the constructor of InvMutTest takes a C _c, so C is already deployed. The test
        // contract does not deploy C. The checker deploys a fresh C and passes it to
        // InvMutTest constructor. So the owner of C is the deployer of C, which is the
        // checker's address, not InvMutTest. Thus InvMutTest is NOT the owner. So a call to
        // withdrawAll from InvMutTest will revert.

        // Therefore, the general rule: withdrawAll reverts when called by non-owner.
        // We can test that: the test contract is not the owner (unless the checker made it so).
        // But we cannot assume the test contract is not owner; the checker may deploy C from
        // InvMutTest? The instructions say: "The checker deploys a FRESH c and runs run(...)
        // exactly ONCE as a single transaction; msg.sender is the InvMutTest contract for
        // every call on c, and this contract deployed c." Wait: "this contract deployed c"
        // means InvMutTest deployed c? But the constructor takes C _c, so InvMutTest does not
        // deploy c. The instructions later say: "Never require() a condition on c's state
        // before the call that creates it." That implies c is already created. The phrase
        // "this contract deployed c" might be a mistake; it says "this contract deployed c"
        // meaning the test contract is the deployer? Actually the checker's setup: it deploys
        // C, then deploys InvMutTest with the address of C. So the owner of C is the
        // checker's address, not InvMutTest. Thus InvMutTest is not the owner. So withdrawAll
        // always reverts when called by InvMutTest. That's the rule we can state.

        // So the rule: withdrawAll always reverts when called by a non-owner. Since
        // InvMutTest is not the owner, it always reverts. But is that general? The rule
        // could be: withdrawAll reverts if and only if the caller is not the owner. Since
        // we cannot test the owner case, we can only assert the non-owner case. But the
        // property must be general: for any caller, if caller is not owner, it reverts.

        // However, the assert must be about the parameters and observable state. We can
        // observe the owner via c.owner(). We can read c.owner() and compare to
        // address(this). If they are different, we expect revert. If they are the same,
        // we expect no revert. So we can write a general rule: withdrawAll reverts exactly
        // when address(this) != c.owner().

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Rule: withdrawAll reverts if and only if the caller is not the owner.
        assert(reverted == (address(this) != ownerBefore));
    }
}

